package template

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"path/filepath"
	"sort"
)

// DescribeOptions selects which template release to inspect. Fields mirror
// CreateOptions for the create flow so callers can share configuration.
type DescribeOptions struct {
	Template  string // required; subdirectory in the templates repo holding template.yaml
	Version   string
	HTTP      *http.Client
	UserAgent string

	// Test overrides; production callers leave these zero-valued.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

func (o *DescribeOptions) applyDefaults() {
	if o.Owner == "" {
		o.Owner = defaultTemplateOwner
	}
	if o.Repo == "" {
		o.Repo = defaultTemplateRepo
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// DescribeResult is the machine-readable view of a template manifest. The
// shape is stable and additive-only — Backstage's frontend renders the form
// from Parameters (a raw JSON Schema), so this contract is load-bearing.
type DescribeResult struct {
	Template    string            `json:"template"`
	Title       string            `json:"title,omitempty"`
	Description string            `json:"description,omitempty"`
	Tags        []string          `json:"tags,omitempty"`
	Labels      map[string]string `json:"labels,omitempty"`
	Owner       string            `json:"owner"`
	Repo        string            `json:"repo"`
	Version     string            `json:"version"`
	Parameters  map[string]any    `json:"parameters"`

	// Dependencies lists the sibling templates this template scaffolds
	// alongside its own output (spec.dependencies).
	Dependencies []DependencySpec `json:"dependencies,omitempty"`

	// orderedFields preserves YAML declaration order for FormatText; YAML
	// order is lost once Parameters round-trips through JSON, so we keep it
	// here. Unexported so it stays out of the wire contract.
	orderedFields []FieldSpec
}

// Describe fetches the template tarball at the requested version (or latest)
// and returns its parsed template manifest. It performs the same fetch+extract
// path as Create but stops short of value resolution or rendering.
func Describe(ctx context.Context, opts DescribeOptions) (*DescribeResult, error) {
	opts.applyDefaults()
	if err := validateTemplateName(opts.Template); err != nil {
		return nil, err
	}

	gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
	tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
	if err != nil {
		return nil, err
	}

	templateRoot, cleanup, err := downloadTemplate(ctx, gh, opts.Owner, opts.Repo, tag, opts.Template, "intropy-describe-*")
	if err != nil {
		return nil, err
	}
	defer cleanup()

	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, err
	}

	return &DescribeResult{
		Template:      tmpl.Metadata.Name,
		Title:         tmpl.Metadata.Title,
		Description:   tmpl.Metadata.Description,
		Tags:          tmpl.Metadata.Tags,
		Labels:        tmpl.Metadata.Labels,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		Version:       tag,
		Parameters:    tmpl.Spec.Parameters,
		Dependencies:  tmpl.Spec.Dependencies,
		orderedFields: tmpl.Fields(),
	}, nil
}

// FormatText writes a human-readable summary of the template to w. The
// machine-readable form is JSON-marshaled DescribeResult — callers needing
// stable parsing should use that instead.
func (r *DescribeResult) FormatText(w io.Writer) {
	title := r.Template
	if r.Title != "" {
		title = fmt.Sprintf("%s (%s)", r.Title, r.Template)
	}
	fmt.Fprintf(w, "%s @ %s/%s@%s\n", title, r.Owner, r.Repo, r.Version)
	if r.Description != "" {
		fmt.Fprintf(w, "\n%s\n", r.Description)
	}
	if len(r.Tags) > 0 {
		fmt.Fprintf(w, "\nTags: %v\n", r.Tags)
	}
	if len(r.Dependencies) > 0 {
		fmt.Fprintln(w, "\nScaffolds alongside (skipped when already present):")
		for _, d := range r.Dependencies {
			fmt.Fprintf(w, "  %s -> ../%s\n", d.Template, d.Output)
		}
	}

	fields := r.orderedFields
	if fields == nil {
		// Result was JSON-unmarshaled by a downstream consumer; declaration
		// order is gone. Fall back to alphabetical so output is at least
		// deterministic.
		fields = fieldsFromSchema(r.Parameters)
	}
	if len(fields) > 0 {
		fmt.Fprintln(w, "\nParameters:")
		for _, f := range fields {
			marker := " "
			if f.Required {
				marker = "*"
			}
			label := f.Name
			if f.Title != "" {
				label = fmt.Sprintf("%s — %s", f.Name, f.Title)
			}
			fmt.Fprintf(w, "  %s %s [%s]\n", marker, label, f.Type)
			if f.Description != "" {
				fmt.Fprintf(w, "      %s\n", f.Description)
			}
			if f.Default != nil {
				fmt.Fprintf(w, "      default: %v\n", f.Default)
			}
			if len(f.Enum) > 0 {
				fmt.Fprintf(w, "      values: %v\n", f.Enum)
			}
			if f.Pattern != "" {
				fmt.Fprintf(w, "      pattern: %s\n", f.Pattern)
			}
		}
		fmt.Fprintln(w, "  (* = required)")
	}
}

// fieldsFromSchema returns FieldSpecs from a raw parameters block. Unlike
// Template.Fields it has no declaration-order information, so it falls back
// to alphabetical order for stable output.
func fieldsFromSchema(parameters map[string]any) []FieldSpec {
	props, _ := parameters["properties"].(map[string]any)
	if props == nil {
		return nil
	}
	required := map[string]bool{}
	if list, ok := parameters["required"].([]any); ok {
		for _, r := range list {
			if s, ok := r.(string); ok {
				required[s] = true
			}
		}
	}
	names := make([]string, 0, len(props))
	for k := range props {
		names = append(names, k)
	}
	sort.Strings(names)
	out := make([]FieldSpec, 0, len(names))
	for _, name := range names {
		raw, _ := props[name].(map[string]any)
		out = append(out, fieldFromSchema(name, raw, required[name]))
	}
	return out
}

package template

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
)

// DefaultLibrary reports the official template library the CLI targets.
//
// Callers outside this package need it to describe what they fetched; the
// constants themselves stay unexported so defaults_test.go remains the one place
// a change to the library source has to be acknowledged.
func DefaultLibrary() (owner, repo string) {
	return defaultTemplateOwner, defaultTemplateRepo
}

// LibraryOptions selects which template library to fetch.
type LibraryOptions struct {
	// Version pins a release tag. Empty resolves the latest release.
	Version string

	HTTP      *http.Client
	UserAgent string
	Stderr    io.Writer

	// Test overrides. Production callers leave these zero-valued.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// Library is a template library extracted on disk at one resolved version.
//
// It exists so a caller rendering several templates pays for one download and
// gets one version across all of them — a component's manifests and its system's
// shared manifests drifting apart by a release would be a subtle, ugly bug. It
// also keeps the on-disk layout of a template package private to this package.
//
// The caller owns the returned Library and must Close it.
type Library struct {
	Owner   string
	Repo    string
	Version string

	root    string
	cleanup func()
}

// FetchLibrary resolves the release tag, downloads the library tarball and
// extracts it.
func FetchLibrary(ctx context.Context, opts LibraryOptions) (*Library, error) {
	owner, repo := DefaultLibrary()
	if opts.Owner != "" {
		owner = opts.Owner
	}
	if opts.Repo != "" {
		repo = opts.Repo
	}
	userAgent := opts.UserAgent
	if userAgent == "" {
		userAgent = "intropy-cli"
	}

	gh := newConfiguredGitHub(opts.HTTP, userAgent, opts.GitHubBaseURL)
	tag, err := gh.ResolveTag(ctx, owner, repo, opts.Version)
	if err != nil {
		return nil, err
	}
	if opts.Stderr != nil {
		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", owner, repo, tag)
	}

	rc, err := gh.Tarball(ctx, owner, repo, tag)
	if err != nil {
		return nil, err
	}
	defer rc.Close()

	tmpDir, err := os.MkdirTemp("", "intropy-library-*")
	if err != nil {
		return nil, err
	}
	cleanup := func() { _ = os.RemoveAll(tmpDir) }
	if err := ExtractTarGz(rc, tmpDir); err != nil {
		cleanup()
		return nil, err
	}
	return &Library{Owner: owner, Repo: repo, Version: tag, root: tmpDir, cleanup: cleanup}, nil
}

// Close removes the extracted copy.
func (l *Library) Close() {
	if l != nil && l.cleanup != nil {
		l.cleanup()
	}
}

// Ref describes the fetched library, for logs and result records.
func (l *Library) Ref() string {
	return fmt.Sprintf("%s/%s@%s", l.Owner, l.Repo, l.Version)
}

// Open loads one template's manifest and returns it with its skeleton root.
//
// The name is validated as a single path segment before it is joined, because it
// is user input turned into a path inside the extracted tarball.
func (l *Library) Open(name string) (*Template, string, error) {
	if err := validateTemplateName(name); err != nil {
		return nil, "", err
	}
	templateRoot := filepath.Join(l.root, name)
	if info, err := os.Stat(templateRoot); err != nil || !info.IsDir() {
		return nil, "", fmt.Errorf("template %q not found in %s", name, l.Ref())
	}
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, "", fmt.Errorf("%s in %s: %w", name, l.Ref(), err)
	}
	skeleton := filepath.Join(templateRoot, templateSkeletonDir)
	if info, err := os.Stat(skeleton); err != nil || !info.IsDir() {
		return nil, "", fmt.Errorf("template %q is missing %s/ directory", name, templateSkeletonDir)
	}
	return tmpl, skeleton, nil
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"text/tabwriter"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/spf13/cobra"
)

// int list walks a directory tree for scaffold records. The walk and the
// record parsing live in internal/template; this file is flag plumbing and
// table formatting.
type intListFlags struct {
	output string
}

var intListOpts intListFlags

var intListCmd = &cobra.Command{
	Use:   "list [dir]",
	Short: "List scaffolded integrations under a directory",
	Long: "Walk the directory tree from dir (default: the current directory) and list every project carrying a " +
		template.ScaffoldRelPath + " record written by `int create`. " +
		"Matched projects are not descended into, and .git, .intropy, node_modules, bin and dist are skipped. " +
		"Use --output json for a machine-readable document including the pinned source and scaffold values.",
	Args: cobra.MaximumNArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(intListOpts.output, "json", "plain"); err != nil {
			return err
		}
		root := "."
		if len(args) == 1 {
			root = args[0]
		}
		if info, err := os.Stat(root); err != nil {
			return fmt.Errorf("list: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("list: %s is not a directory", root)
		}

		entries, warnings := template.ListScaffolds(root)
		for _, w := range warnings {
			fmt.Fprintln(cmd.ErrOrStderr(), "warning:", w)
		}

		if intListOpts.output == "json" {
			if entries == nil {
				entries = []template.ScaffoldEntry{}
			}
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(entries)
		}

		if len(entries) == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "no scaffolded integrations found")
			return nil
		}

		tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
		fmt.Fprintln(tw, "PATH\tTEMPLATE\tVERSION")
		for _, e := range entries {
			fmt.Fprintf(tw, "%s\t%s\t%s\n", e.Path, e.Template, e.Version)
		}
		return tw.Flush()
	},
}

func init() {
	f := intListCmd.Flags()
	f.StringVarP(&intListOpts.output, "output", "o", "plain", flagUsageOutput)
	intCmd.AddCommand(intListCmd)
}

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// TemplateRoleLabel names the manifest label that declares what role a
	// template's output plays in a system. Its value is copied into the
	// scaffold record so later commands can tell support projects apart
	// from system blocks.
	TemplateRoleLabel = "intropy.dev/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel = "intropy.dev/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in" or "out").
	// Recorded alongside the block kind.
	TemplateDataFlowLabel = "intropy.dev/data-flow"

	// BlockKindExtractor and BlockKindLoader are the block kinds `sys
	// create` knows how to assemble.
	BlockKindExtractor = "extractor"
	BlockKindLoader    = "loader"
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g. `sys
// create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int            `json:"schemaVersion"`
	Template      string         `json:"template"` // directory name in the template library repo
	Owner         string         `json:"owner"`
	Repo          string         `json:"repo"`
	Version       string         `json:"version"`
	Values        map[string]any `json:"values"`

	// Role is the value of the template's intropy.dev/template-role label,
	// if any (e.g. "shared-library").
	Role string `json:"role,omitempty"`

	// BlockKind is the value of the template's intropy.dev/block-kind
	// label, if any (e.g. "extractor").
	BlockKind string `json:"blockKind,omitempty"`

	// DataFlow is the value of the template's intropy.dev/data-flow label,
	// if any ("in" or "out").
	DataFlow string `json:"dataFlow,omitempty"`

	// DependsOn lists the sibling projects this project's template declared
	// under spec.dependencies, whether the render created them or they
	// already existed.
	DependsOn []DependencyRecord `json:"dependsOn,omitempty"`
}

// DependencyRecord points at a sibling project a component depends on. Dir
// is slash-separated and relative to the component root (e.g. "../Acme.Models").
type DependencyRecord struct {
	Template string `json:"template"`
	Dir      string `json:"dir"`
}

func roleFromLabels(labels map[string]string) string {
	return labels[TemplateRoleLabel]
}

func blockKindFromLabels(labels map[string]string) string {
	return labels[TemplateBlockKindLabel]
}

func dataFlowFromLabels(labels map[string]string) string {
	return labels[TemplateDataFlowLabel]
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}

package main

import (
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

var (
	noColorFlag   bool
	changeDirFlag string
)

var rootCmd = &cobra.Command{
	Use:           "intropy",
	Short:         "Intropy CLI",
	Long:          "intropy is the command-line interface for working with Intropy skills and integrations.",
	Version:       version,
	SilenceUsage:  true,
	SilenceErrors: true,
	PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
		if changeDirFlag == "" {
			return nil
		}
		if err := os.Chdir(changeDirFlag); err != nil {
			return fmt.Errorf("cannot change to directory %q: %w", changeDirFlag, err)
		}
		return nil
	},
}

func Execute() error {
	if err := rootCmd.Execute(); err != nil {
		fmt.Fprintln(rootCmd.ErrOrStderr(), "error:", err)
		return err
	}
	return nil
}

// validateOutputFlag returns a usageError if the given format is not in the
// allowed set. Use this for --output flags that accept a fixed list of formats.
func validateOutputFlag(format string, allowed ...string) error {
	for _, a := range allowed {
		if format == a {
			return nil
		}
	}
	return newUsageErrorf("invalid output format %q (allowed: %v)", format, allowed)
}

func init() {
	rootCmd.PersistentFlags().BoolVar(&noColorFlag, "no-color", false, "disable colored output")
	rootCmd.PersistentFlags().StringVarP(&changeDirFlag, "directory", "C", "", "change to directory before running the command")
	_ = rootCmd.MarkPersistentFlagDirname("directory")
}

