	if err != nil {
		return nil, fmt.Errorf("download tarball: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		resp.Body.Close()
		return nil, fmt.Errorf("download tarball: %s: %s", resp.Status, string(body))
	}
	return resp.Body, nil
}

// ListTemplates returns the names of template directories at the root of
// the templates repository. On any error an empty slice is returned.
func (g *GitHub) ListTemplates(ctx context.Context, owner, repo string) ([]string, error) {
	if owner == "" {
		owner = defaultTemplateOwner
	}
	if repo == "" {
		repo = defaultTemplateRepo
	}
	u := fmt.Sprintf("%s/repos/%s/%s/contents/", g.BaseURL, owner, repo)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	g.addCommonHeaders(req)

	resp, err := g.HTTP.Do(req)
	if err != nil {
		return nil, fmt.Errorf("list contents: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return nil, fmt.Errorf("list contents: %s: %s", resp.Status, string(body))
	}

	var entries []struct {
		Name string `json:"name"`
		Type string `json:"type"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&entries); err != nil {
		return nil, fmt.Errorf("decode contents: %w", err)
	}

	var dirs []string
	for _, e := range entries {
		if e.Type == "dir" {
			dirs = append(dirs, e.Name)
		}
	}
	return dirs, nil
}

func (g *GitHub) addCommonHeaders(req *http.Request) {
	if g.UserAgent != "" {
		req.Header.Set("User-Agent", g.UserAgent)
	}
	if g.Token != "" {
		req.Header.Set("Authorization", "Bearer "+g.Token)
	}
}

package main

// Shared flag descriptions. A flag that appears on more than one command
// uses the constant here rather than a hand-written string, so the help
// text cannot drift between commands. See AGENTS.md.
const (
	// flagUsageOutput is the --output description for commands whose plain
	// output is human-readable and whose json output goes to stdout.
	flagUsageOutput = "output format (plain, json)"

	// flagUsageOutputJSONOnly is the --output description for the two
	// scaffold commands (int create, sys create), whose only format is a
	// JSON result document.
	flagUsageOutputJSONOnly = "output format: 'json' writes the result document to stdout"

	// flagUsageEnv is the --env description for deploy subcommands that
	// take a single target environment.
	flagUsageEnv = "target environment (required)"

